# effective-profile-readback.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/effective-profile-readback.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "bindings": {
      "additionalProperties": false,
      "properties": {
        "bond_id": {
          "pattern": "^b-[0-9]{8}-[0-9]{4}-[a-z0-9-]+$",
          "type": "string"
        },
        "parent_bond_id": {
          "pattern": "^b-[0-9]{8}-[0-9]{4}-[a-z0-9-]+$",
          "type": [
            "string",
            "null"
          ]
        },
        "room_id": {
          "pattern": "^(obj|task|space)-[a-z0-9-]+$",
          "type": "string"
        },
        "session_id": {
          "minLength": 1,
          "type": "string"
        },
        "thread_root": {
          "minimum": 1,
          "type": "integer"
        },
        "work_uid": {
          "pattern": "^work-[A-Za-z0-9][A-Za-z0-9._-]*$",
          "type": "string"
        }
      },
      "required": [
        "room_id",
        "thread_root",
        "work_uid"
      ],
      "type": "object"
    },
    "desired_digest": {
      "pattern": "^sha256:[0-9a-f]{64}$",
      "type": "string"
    },
    "desired_revision": {
      "minimum": 1,
      "type": "integer"
    },
    "drifted": {
      "type": "boolean"
    },
    "effective_digest": {
      "pattern": "^sha256:[0-9a-f]{64}$",
      "type": "string"
    },
    "effective_revision": {
      "minimum": 1,
      "type": "integer"
    },
    "identity": {
      "$ref": "profile-identity.schema.json"
    },
    "policy_owner": {
      "pattern": "^pr-[a-z0-9-]+$",
      "type": "string"
    },
    "protected_state_refs": {
      "items": {
        "minLength": 1,
        "type": "string"
      },
      "type": "array",
      "uniqueItems": true
    },
    "provenance": {
      "additionalProperties": {
        "minLength": 1,
        "type": "string"
      },
      "minProperties": 1,
      "type": "object"
    },
    "readback_id": {
      "pattern": "^rb-[a-z0-9-]+$",
      "type": "string"
    },
    "schema_version": {
      "const": 1
    },
    "source_ref": {
      "pattern": "^/chd/effective-readback/[A-Za-z0-9._/-]+$",
      "type": "string"
    }
  },
  "required": [
    "schema_version",
    "readback_id",
    "desired_revision",
    "effective_revision",
    "desired_digest",
    "effective_digest",
    "identity",
    "bindings",
    "policy_owner",
    "provenance",
    "drifted",
    "source_ref"
  ],
  "title": "CHD effective profile readback",
  "type": "object"
}
```
